def all_items():
    """Yield dicts ready for QuestionBankItem(**d)."""
    import json
    for topic, items in TECHNICAL.items():
        for diff, q, ideal, kps in items:
            yield {"interview_type": "technical", "topic": topic, "difficulty": diff, "question": q,
                   "ideal_answer": ideal, "key_points": json.dumps([{"label": l, "terms": t} for l, t in kps]), "source": "seed"}
    for diff, q, ideal, kps in HR:
        yield {"interview_type": "hr", "topic": "hr", "difficulty": diff, "question": q, "ideal_answer": ideal,
               "key_points": json.dumps([{"label": l, "terms": t} for l, t in kps]), "source": "seed"}
